import java.lang.reflect.*;
import java.util.*;

interface Service { void exec(); }
class ServiceImpl implements Service { public void exec() { System.out.println("    [Target] exec()"); } }
interface Advice { void before(); void after(); }
class ABefore implements Advice { public void before() { System.out.println("  [Before] log"); } public void after() {} }
class AAfter implements Advice { public void before() {} public void after() { System.out.println("  [After] cleanup"); } }
class ChainHandler implements InvocationHandler {
    Object target; List<Advice> advices;
    ChainHandler(Object t, List<Advice> l) { target = t; advices = l; }
    public Object invoke(Object p, Method m, Object[] args) throws Throwable {
        System.out.println("[Around] start");
        for (Advice ad : advices) ad.before();
        Object r = m.invoke(target, args);
        for (int i = advices.size() - 1; i >= 0; i--) advices.get(i).after();
        System.out.println("[Around] end");
        return r;
    }
}
public class Main {
    public static void main(String[] a) throws Exception {
        List<Advice> l = new ArrayList<>();
        l.add(new ABefore()); l.add(new AAfter());
        Service proxy = (Service) Proxy.newProxyInstance(Service.class.getClassLoader(),
            new Class[]{Service.class}, new ChainHandler(new ServiceImpl(), l));
        proxy.exec();
    }
}
